/**
 * Early-instrumentation entrypoint: `import "@sazabi/browser/register"`.
 *
 * Importing this module installs the SDK's fetch/XHR/history patches as
 * dormant, transparent passthroughs at module-evaluation time — before any
 * other library's module-scope code can capture the native functions (the
 * race `init()` alone cannot win, since every static import in an app's
 * entry file evaluates before its first statement). `init()` later activates
 * them with configuration; until then they observe nothing, store nothing,
 * and send nothing.
 *
 * Put this import above all other imports in your application entry module.
 */
import { isReactNativeHost } from "./host";
import { ensureNavigationPatches } from "./navigation";
import { ensureNetworkPatches } from "./network";

// React Native aliases `window` to its global, so the SSR guard alone would
// wrap its XMLHttpRequest with a copy of the core that nothing ever activates;
// the mobile SDK, bundled with its own copy, would then see the shared wrapper
// marker and skip its own patch. The host belongs to @sazabi/react-native.
if (typeof window !== "undefined" && !isReactNativeHost()) {
  try {
    ensureNetworkPatches();
    ensureNavigationPatches();
  } catch {
    // Registration must never break the host app; init() re-ensures.
  }
}
